-- =========================================================
--  SCRIPT DE AUDITORÍA DE BASE DE DATOS
-- =========================================================

-- [1] LIMPIEZA PREVIA (Opcional, descomentar si se requiere reiniciar auditoría)
-- DROP TABLE "APP_OWNER"."AUDITORIA_OPERACIONES";

-- [2] CREACIÓN DE LA TABLA CENTRALIZADA DE AUDITORÍA

CREATE TABLE "APP_OWNER"."AUDITORIA_OPERACIONES" (
    "ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
    "TABLA_AFECTADA" VARCHAR2(50),
    "ID_REGISTRO" VARCHAR2(50),     
    "OPERACION" VARCHAR2(10),      
    "COLUMNA_MODIFICADA" VARCHAR2(50),
    "VALOR_ANTERIOR" VARCHAR2(4000),
    "VALOR_NUEVO" VARCHAR2(4000),
    "DB_USER" VARCHAR2(50),       
    "OS_USER" VARCHAR2(50),     
    "REAL_USER" VARCHAR2(50),        
    "FECHA_EVENTO" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP,
    CONSTRAINT "PK_AUDITORIA" PRIMARY KEY ("ID")
);

-- [3] TRIGGERS DE SEGURIDAD OPERATIVA (STOCK Y PEDIDOS)

-- 3.1. Auditoría de SALDOS_INVENTARIO
-- Objetivo: Detectar ajustes manuales de stock fuera de los procesos normales.
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_SALDOS_INV"
AFTER UPDATE ON "APP_OWNER"."SALDOS_INVENTARIO"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    -- Cambio en Existencia Física
    IF :OLD.EXISTENCIA != :NEW.EXISTENCIA THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES 
        ('SALDOS_INVENTARIO', TO_CHAR(:OLD.VARIANTE_PRODUCTO_ID), 'UPDATE', 'EXISTENCIA', TO_CHAR(:OLD.EXISTENCIA), TO_CHAR(:NEW.EXISTENCIA), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
    
    -- Cambio en Stock Reservado
    IF :OLD.RESERVADO != :NEW.RESERVADO THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES 
        ('SALDOS_INVENTARIO', TO_CHAR(:OLD.VARIANTE_PRODUCTO_ID), 'UPDATE', 'RESERVADO', TO_CHAR(:OLD.RESERVADO), TO_CHAR(:NEW.RESERVADO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- 3.2. Auditoría de PEDIDOS
-- Objetivo: Detectar cancelaciones forzadas o cambios en el monto total a cobrar.
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_PEDIDOS"
AFTER UPDATE ON "APP_OWNER"."PEDIDOS"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    -- Cambio de Estado (ej. Pagado -> Cancelado)
    IF :OLD.ESTADO != :NEW.ESTADO THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES 
        ('PEDIDOS', TO_CHAR(:OLD.ID), 'UPDATE', 'ESTADO', :OLD.ESTADO, :NEW.ESTADO, USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;

    -- Cambio de Total (Riesgo de fraude financiero)
    IF :OLD.TOTAL_PRECIO != :NEW.TOTAL_PRECIO THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES 
        ('PEDIDOS', TO_CHAR(:OLD.ID), 'UPDATE', 'TOTAL_PRECIO', TO_CHAR(:OLD.TOTAL_PRECIO), TO_CHAR(:NEW.TOTAL_PRECIO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- 3.3. Auditoría de DETALLE_PEDIDOS
-- Objetivo: Detectar "robo hormiga" o manipulación de líneas dentro de un pedido.
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_DETALLE_PEDIDOS"
AFTER UPDATE OR DELETE ON "APP_OWNER"."DETALLE_PEDIDOS"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    IF UPDATING THEN
        -- Cambio de Precio Unitario
        IF :OLD.PRECIO_UNITARIO != :NEW.PRECIO_UNITARIO THEN
            INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
            (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
            VALUES ('DETALLE_PEDIDOS', TO_CHAR(:OLD.ID), 'UPDATE', 'PRECIO_UNITARIO', TO_CHAR(:OLD.PRECIO_UNITARIO), TO_CHAR(:NEW.PRECIO_UNITARIO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
        END IF;
        -- Cambio de Cantidad
        IF :OLD.CANTIDAD != :NEW.CANTIDAD THEN
            INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
            (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
            VALUES ('DETALLE_PEDIDOS', TO_CHAR(:OLD.ID), 'UPDATE', 'CANTIDAD', TO_CHAR(:OLD.CANTIDAD), TO_CHAR(:NEW.CANTIDAD), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
        END IF;
    END IF;

    -- Eliminación de Items (Muy sospechoso en pedidos ya creados)
    IF DELETING THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES ('DETALLE_PEDIDOS', TO_CHAR(:OLD.ID), 'DELETE', 'REGISTRO_COMPLETO', 'Prod_ID:'||:OLD.PRODUCTO_ID, 'ELIMINADO', USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- [4] TRIGGERS DE SEGURIDAD COMERCIAL (PRECIOS Y CUPONES)

-- 4.1. Auditoría de PRECIOS EN VARIANTES
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_PRECIOS_VAR"
AFTER UPDATE ON "APP_OWNER"."VARIANTES_PRODUCTO"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    IF NVL(:OLD.PRECIO_SOBRESCRITO, -1) != NVL(:NEW.PRECIO_SOBRESCRITO, -1) THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES 
        ('VARIANTES_PRODUCTO', :OLD.SKU, 'UPDATE', 'PRECIO_SOBRESCRITO', TO_CHAR(:OLD.PRECIO_SOBRESCRITO), TO_CHAR(:NEW.PRECIO_SOBRESCRITO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- 4.2. Auditoría de PRECIOS BASE (Productos sin variantes)
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_PRODUCTOS_BASE"
AFTER UPDATE ON "APP_OWNER"."PRODUCTOS"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    IF :OLD.PRECIO != :NEW.PRECIO THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES ('PRODUCTOS', TO_CHAR(:OLD.ID), 'UPDATE', 'PRECIO', TO_CHAR(:OLD.PRECIO), TO_CHAR(:NEW.PRECIO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- 4.3. Auditoría de CUPONES (Anti-fraude de marketing)
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_CUPONES"
AFTER UPDATE ON "APP_OWNER"."CUPONES"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
BEGIN
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    -- Cambio drástico de valor
    IF :OLD.VALOR_DESCUENTO != :NEW.VALOR_DESCUENTO THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES ('CUPONES', :OLD.CODIGO, 'UPDATE', 'VALOR_DESCUENTO', TO_CHAR(:OLD.VALOR_DESCUENTO), TO_CHAR(:NEW.VALOR_DESCUENTO), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;

    -- Reactivación de cupón vencido
    IF :OLD.VIGENTE_HASTA != :NEW.VIGENTE_HASTA THEN
        INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
        (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
        VALUES ('CUPONES', :OLD.CODIGO, 'UPDATE', 'VIGENTE_HASTA', TO_CHAR(:OLD.VIGENTE_HASTA, 'DD/MM/YYYY'), TO_CHAR(:NEW.VIGENTE_HASTA, 'DD/MM/YYYY'), USER, SYS_CONTEXT('USERENV', 'OS_USER'), v_real_user);
    END IF;
END;
/

-- [5] ALERTA DE INTEGRIDAD (BITÁCORA DE MOVIMIENTOS)

-- 5.1. Protección de MOVIMIENTOS_INVENTARIO
CREATE OR REPLACE TRIGGER "APP_OWNER"."TG_AUDIT_MOVIMIENTOS_SECURITY"
BEFORE UPDATE OR DELETE ON "APP_OWNER"."MOVIMIENTOS_INVENTARIO"
FOR EACH ROW
DECLARE
    v_real_user VARCHAR2(50);
    v_operacion VARCHAR2(10); -- Variable auxiliar para corregir el error
BEGIN
    -- 1. Obtener usuario real
    v_real_user := NVL(SYS_CONTEXT('USERENV', 'PROXY_USER'), USER);

    -- 2. Determinar la operación en lógica PL/SQL (aquí sí funciona UPDATING/DELETING)
    IF UPDATING THEN
        v_operacion := 'UPDATE';
    ELSE
        v_operacion := 'DELETE';
    END IF;
    
    -- 3. Insertar usando la variable
    INSERT INTO "APP_OWNER"."AUDITORIA_OPERACIONES" 
    (TABLA_AFECTADA, ID_REGISTRO, OPERACION, COLUMNA_MODIFICADA, VALOR_ANTERIOR, VALOR_NUEVO, DB_USER, OS_USER, REAL_USER)
    VALUES 
    ('MOVIMIENTOS_INVENTARIO', 
     TO_CHAR(:OLD.ID), 
     v_operacion,  -- Usamos la variable en lugar del CASE
     'SEGURIDAD_CRITICA', 
     'Intento de alterar historial', 
     'ALERTA_ROJA', 
     USER, 
     SYS_CONTEXT('USERENV', 'OS_USER'), 
     v_real_user);
END;
/
